(function(){const nav=document.querySelector('.app-nav');if(nav){nav.addEventListener('toggle',function(e){if(e.target.tagName==='DETAILS'&&e.target.open)nav.querySelectorAll('details[open]').forEach(function(d){if(d!==e.target)d.removeAttribute('open')})},true);document.addEventListener('click',function(e){if(!nav.contains(e.target))nav.querySelectorAll('details[open]').forEach(function(d){d.removeAttribute('open')})});nav.addEventListener('keydown',function(e){if(e.key==='Escape'){nav.querySelectorAll('details[open]').forEach(function(d){d.removeAttribute('open')});nav.querySelector('summary:focus, a:focus')?.focus()}})}const csrfToken=<?=json_encode(csrfToken(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;function protect(form){if((form.method||'get').toLowerCase()==='post'&&!form.querySelector('input[name="_csrf_token"]')){const token=document.createElement('input');token.type='hidden';token.name='_csrf_token';token.value=csrfToken;form.prepend(token)}}document.querySelectorAll('form').forEach(protect);document.addEventListener('submit',function(e){protect(e.target)},true)})();
</script><?php endif;?>
